import React, { useState, useMemo } from "react";

const IMG = {
  hero: "data:image/jpeg;base64,",
  spin: "data:image/jpeg;base64,",
  futurity: "data:image/jpeg;base64,",
  tulsa: "data:image/jpeg;base64,",
  qualifier: "data:image/jpeg;base64,",
};

// ---- Tokens ----
const C = {
  accent: "#15803D", accent500: "#16A34A", accent50: "#DCFCE7", accentDim: "rgba(21,128,61,0.08)",
  ink: "#0B1120", ink900: "#0F172A",
  slate700: "#334155", slate500: "#64748B", slate400: "#94A3B8", slate300: "#CBD5E1",
  slate100: "#F1F5F9", slate50: "#F8FAFC", white: "#FFFFFF",
  live: "#DC2626", info: "#1D4ED8", warn: "#B45309",
  gold: "#C8902F", goldLight: "#E8B84B",
};

// tier → trattamento
const TIER = {
  regionale:      { label: "Regionale",      bg: "rgba(21,128,61,0.10)",  fg: "#15803D", accent: "#15803D" },
  nazionale:      { label: "Nazionale",      bg: "rgba(29,78,216,0.10)",  fg: "#1D4ED8", accent: "#1D4ED8" },
  internazionale: { label: "Internazionale", bg: "rgba(29,78,216,0.12)",  fg: "#1D4ED8", accent: "#1D4ED8" },
  premium:        { label: "Premium",        bg: "#0F172A",               fg: "#E8B84B", accent: "#C8902F" },
};

// ---- Data ----
const EVENTS = [
  { id: 1, day: "12", month: "Apr", name: "Lombardia Reining · 2ª tappa", venue: "Circolo Le Valli, Cremona", tier: "regionale", img: IMG.spin, region: "Lombardia", status: "open" },
  { id: 2, day: "24", month: "Mag", name: "Coppa delle Regioni IRHA-FISE", venue: "23 Quarter Horses, Asti", tier: "nazionale", img: IMG.qualifier, region: "Piemonte", status: "open" },
  { id: 3, day: "28", month: "Giu", name: "European Reining Championship", venue: "Cremona Arena", tier: "internazionale", img: IMG.tulsa, region: "Lombardia", status: "live" },
  { id: 4, day: "15", month: "Nov", name: "IRHA Futurity", venue: "Cremona Arena", tier: "premium", img: IMG.futurity, region: "Lombardia", status: "announced", prize: "€120.000" },
];

const REGIONS = ["Tutte", "Lombardia", "Piemonte", "Emilia-Romagna", "Veneto"];

export default function App() {
  const [region, setRegion] = useState("Tutte");
  const [q, setQ] = useState("");

  const filtered = useMemo(() => {
    return EVENTS.filter((e) => {
      const okRegion = region === "Tutte" || e.region === region;
      const okQ = !q || e.name.toLowerCase().includes(q.toLowerCase()) || e.venue.toLowerCase().includes(q.toLowerCase());
      return okRegion && okQ;
    });
  }, [region, q]);

  const liveEvent = EVENTS.find((e) => e.status === "live");

  return (
    <div style={{ fontFamily: "Inter, system-ui, sans-serif", background: C.slate50, minHeight: "100vh", color: C.ink900 }}>

      {/* ===== HERO (scuro, cinematografico) ===== */}
      <div style={{ position: "relative", background: C.ink }}>
        <div style={{ position: "absolute", inset: 0, backgroundImage: `url(${IMG.hero})`, backgroundSize: "cover", backgroundPosition: "center 25%" }} />
        <div style={{ position: "absolute", inset: 0, background: "linear-gradient(to right, #0B1120 8%, rgba(11,17,32,0.78) 52%, rgba(11,17,32,0.35) 100%)" }} />

        {/* nav */}
        <div style={{ position: "relative", maxWidth: 1100, margin: "0 auto", padding: "16px 24px", display: "flex", alignItems: "center", gap: 12 }}>
          <div style={{ width: 28, height: 28, borderRadius: 7, background: C.accent, display: "flex", alignItems: "center", justifyContent: "center", fontWeight: 800, fontSize: 15, color: "#fff" }}>P</div>
          <span style={{ fontSize: 17, fontWeight: 700, color: "#fff", letterSpacing: "-0.3px" }}>PenRunner</span>
          <div style={{ marginLeft: "auto", display: "flex", gap: 22, alignItems: "center" }}>
            <NavLink>Calendario</NavLink>
            <NavLink>Risultati</NavLink>
            <NavLink>Cavalli &amp; cavalieri</NavLink>
            <button style={{ background: "rgba(255,255,255,0.1)", color: "#fff", border: "1px solid rgba(255,255,255,0.18)", borderRadius: 8, padding: "8px 15px", fontSize: 13, fontWeight: 600, cursor: "pointer", fontFamily: "inherit" }}>Accedi</button>
          </div>
        </div>

        {/* hero content */}
        <div style={{ position: "relative", maxWidth: 1100, margin: "0 auto", padding: "44px 24px 52px" }}>
          <div style={{ maxWidth: 560 }}>
            <div style={{ fontSize: 13, fontWeight: 600, color: C.accent500, textTransform: "uppercase", letterSpacing: "1.5px", marginBottom: 12 }}>Il reining italiano, in diretta</div>
            <h1 style={{ fontSize: 40, fontWeight: 800, color: "#fff", letterSpacing: "-1px", lineHeight: 1.08, margin: "0 0 14px" }}>Ogni gara, ogni punteggio, ogni cavallo.</h1>
            <p style={{ fontSize: 16, color: C.slate300, lineHeight: 1.6, margin: "0 0 24px" }}>Segui le competizioni IRHA-FISE in tempo reale, scopri gli eventi in arrivo e ritrova i risultati di ogni binomio.</p>

            {/* search */}
            <div style={{ display: "flex", gap: 9, maxWidth: 440 }}>
              <div style={{ flex: 1, position: "relative" }}>
                <span style={{ position: "absolute", left: 13, top: "50%", transform: "translateY(-50%)", color: C.slate400 }}><SearchIcon /></span>
                <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Cerca eventi, cavalli, cavalieri…"
                  style={{ width: "100%", height: 46, background: "rgba(255,255,255,0.96)", border: "none", borderRadius: 10, padding: "0 14px 0 40px", fontSize: 14, fontFamily: "inherit", outline: "none", boxSizing: "border-box", color: C.ink900 }} />
              </div>
            </div>
          </div>

          {/* live ticker */}
          {liveEvent && (
            <div onClick={() => alert("Apre la pagina evento con i live results.")}
              style={{ marginTop: 30, display: "inline-flex", alignItems: "center", gap: 13, background: "rgba(11,17,32,0.6)", backdropFilter: "blur(8px)", border: `1px solid rgba(220,38,38,0.4)`, borderRadius: 12, padding: "12px 16px", cursor: "pointer" }}>
              <span style={{ position: "relative", width: 9, height: 9, flexShrink: 0 }}>
                <span style={{ position: "absolute", inset: 0, borderRadius: "50%", background: C.live, animation: "pulse 1.4s ease-in-out infinite" }} />
              </span>
              <div>
                <div style={{ fontSize: 11, fontWeight: 600, color: C.live, textTransform: "uppercase", letterSpacing: "0.8px" }}>In diretta ora</div>
                <div style={{ fontSize: 14, fontWeight: 600, color: "#fff", marginTop: 1 }}>{liveEvent.name}</div>
              </div>
              <span style={{ marginLeft: 8, color: C.slate300, fontSize: 18 }}>→</span>
            </div>
          )}
        </div>
      </div>

      {/* ===== BODY (chiaro) ===== */}
      <div style={{ maxWidth: 1100, margin: "0 auto", padding: "36px 24px 56px" }}>

        {/* section header + filters */}
        <div style={{ display: "flex", alignItems: "flex-end", justifyContent: "space-between", flexWrap: "wrap", gap: 14, marginBottom: 20 }}>
          <div>
            <h2 style={{ fontSize: 24, fontWeight: 700, letterSpacing: "-0.5px", margin: "0 0 3px" }}>Calendario eventi</h2>
            <p style={{ fontSize: 13.5, color: C.slate500, margin: 0 }}>L'importanza di ogni evento si legge dal colore.</p>
          </div>
          <div style={{ display: "flex", gap: 7, flexWrap: "wrap" }}>
            {REGIONS.map((r) => (
              <button key={r} onClick={() => setRegion(r)}
                style={{ fontSize: 12.5, fontWeight: 500, padding: "7px 13px", borderRadius: 8, cursor: "pointer", fontFamily: "inherit", border: region === r ? "none" : `1px solid rgba(15,23,42,0.12)`, background: region === r ? C.ink900 : "#fff", color: region === r ? "#fff" : C.slate700 }}>
                {r}
              </button>
            ))}
          </div>
        </div>

        {/* event cards */}
        {filtered.length === 0 ? (
          <div style={{ padding: "48px", textAlign: "center", color: C.slate400, fontSize: 14, background: "#fff", borderRadius: 12, border: `1px solid rgba(15,23,42,0.08)` }}>
            Nessun evento per questa ricerca. Prova a cambiare regione o termine.
          </div>
        ) : (
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(248px, 1fr))", gap: 16 }}>
            {filtered.map((e) => <EventCard key={e.id} e={e} />)}
          </div>
        )}

        {/* quick links row */}
        <div style={{ marginTop: 40, display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(220px, 1fr))", gap: 14 }}>
          <QuickCard icon={<TrophyIcon />} title="Risultati e classifiche" desc="Sfoglia gli esiti di ogni go-round e finale." />
          <QuickCard icon={<HorseIcon />} title="Cavalli e cavalieri" desc="Cerca un binomio e ripercorri il suo storico." />
          <QuickCard icon={<FlagIcon />} title="Organizzi un evento?" desc="Porta la tua gara su PenRunner." cta />
        </div>
      </div>

      {/* footer */}
      <div style={{ background: C.ink900, color: C.slate400, padding: "28px 24px" }}>
        <div style={{ maxWidth: 1100, margin: "0 auto", display: "flex", alignItems: "center", gap: 12, flexWrap: "wrap" }}>
          <div style={{ width: 24, height: 24, borderRadius: 6, background: C.accent, display: "flex", alignItems: "center", justifyContent: "center", fontWeight: 800, fontSize: 13, color: "#fff" }}>P</div>
          <span style={{ fontSize: 14, fontWeight: 600, color: "#fff" }}>PenRunner</span>
          <span style={{ fontSize: 12.5, marginLeft: 8 }}>Il gestionale delle gare di reining</span>
          <span style={{ marginLeft: "auto", fontSize: 12 }}>IRHA · FISE · Italia</span>
        </div>
      </div>

      <style>{`
        @keyframes pulse { 0%,100%{opacity:1;transform:scale(1)} 50%{opacity:0.4;transform:scale(1.18)} }
        @media (prefers-reduced-motion: reduce){ *{animation:none !important} }
      `}</style>
    </div>
  );
}

function EventCard({ e }) {
  const t = TIER[e.tier];
  const premium = e.tier === "premium";
  const intl = e.tier === "internazionale";

  // Premium: card scura con oro. Internazionale: header pieno colore tema. Altri: chiaro con accento.
  if (premium) {
    return (
      <div style={{ borderRadius: 13, overflow: "hidden", border: `1.5px solid ${C.gold}`, cursor: "pointer", background: C.ink900 }}>
        <div style={{ position: "relative", height: 124, backgroundImage: `url(${e.img})`, backgroundSize: "cover", backgroundPosition: "center 35%" }}>
          <div style={{ position: "absolute", inset: 0, background: "linear-gradient(to top, rgba(15,23,42,0.9), rgba(15,23,42,0.2))" }} />
          <span style={{ position: "absolute", top: 10, left: 10, fontSize: 10, fontWeight: 600, background: C.gold, color: "#1A1206", padding: "3px 9px", borderRadius: 5, display: "inline-flex", alignItems: "center", gap: 4 }}>♦ Premium</span>
          {e.prize && <span style={{ position: "absolute", bottom: 10, right: 12, fontSize: 12, fontWeight: 700, color: C.goldLight, fontVariantNumeric: "tabular-nums" }}>{e.prize}</span>}
        </div>
        <div style={{ padding: "13px 15px" }}>
          <div style={{ fontSize: 11, color: C.goldLight, marginBottom: 3, fontVariantNumeric: "tabular-nums" }}>{e.day} {e.month}</div>
          <div style={{ fontSize: 15, fontWeight: 700, color: "#fff", lineHeight: 1.2 }}>{e.name}</div>
          <div style={{ fontSize: 12, color: C.slate400, marginTop: 3 }}>{e.venue}</div>
          <div style={{ marginTop: 10, fontSize: 11.5, fontWeight: 600, color: C.goldLight }}>Annunciato · iscrizioni a breve</div>
        </div>
      </div>
    );
  }

  if (intl) {
    return (
      <div style={{ borderRadius: 13, overflow: "hidden", border: `1.5px solid ${t.accent}`, cursor: "pointer", background: "#fff" }}>
        <div style={{ position: "relative", height: 116, backgroundImage: `url(${e.img})`, backgroundSize: "cover", backgroundPosition: "center" }}>
          <div style={{ position: "absolute", inset: 0, background: `linear-gradient(to top, ${t.accent}E6, ${t.accent}44)` }} />
          {e.status === "live" && <span style={{ position: "absolute", top: 10, left: 10, fontSize: 10, fontWeight: 600, background: C.live, color: "#fff", padding: "3px 9px", borderRadius: 5, display: "inline-flex", alignItems: "center", gap: 5 }}><span style={{ width: 5, height: 5, borderRadius: "50%", background: "#fff", animation: "pulse 1.4s ease-in-out infinite" }} /> IN DIRETTA</span>}
          <div style={{ position: "absolute", left: 0, right: 0, bottom: 0, padding: "11px 14px" }}>
            <div style={{ fontSize: 11, color: "rgba(255,255,255,0.8)", fontVariantNumeric: "tabular-nums" }}>{e.day} {e.month} · {t.label}</div>
            <div style={{ fontSize: 15, fontWeight: 700, color: "#fff", lineHeight: 1.2 }}>{e.name}</div>
          </div>
        </div>
        <div style={{ padding: "11px 14px" }}>
          <div style={{ fontSize: 12, color: C.slate500 }}>{e.venue}</div>
        </div>
      </div>
    );
  }

  // regionale / nazionale: chiaro, accento sul bordo-sinistro + miniatura
  return (
    <div style={{ borderRadius: 13, overflow: "hidden", border: `1px solid rgba(15,23,42,0.08)`, borderLeft: `4px solid ${t.accent}`, cursor: "pointer", background: "#fff" }}>
      <div style={{ height: 104, backgroundImage: `url(${e.img})`, backgroundSize: "cover", backgroundPosition: "center" }} />
      <div style={{ padding: "12px 14px" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 5 }}>
          <span style={{ fontSize: 10, fontWeight: 600, background: t.bg, color: t.fg, padding: "3px 8px", borderRadius: 5 }}>{t.label}</span>
          <span style={{ fontSize: 11.5, color: C.slate400, fontVariantNumeric: "tabular-nums" }}>{e.day} {e.month}</span>
        </div>
        <div style={{ fontSize: 14.5, fontWeight: 600, lineHeight: 1.25 }}>{e.name}</div>
        <div style={{ fontSize: 12, color: C.slate500, marginTop: 3 }}>{e.venue}</div>
        <div style={{ marginTop: 9, fontSize: 11.5, fontWeight: 600, color: C.accent }}>Iscrizioni aperte →</div>
      </div>
    </div>
  );
}

function QuickCard({ icon, title, desc, cta }) {
  return (
    <div style={{ background: cta ? C.ink900 : "#fff", border: cta ? "none" : `1px solid rgba(15,23,42,0.08)`, borderRadius: 12, padding: "18px 18px", cursor: "pointer" }}>
      <div style={{ width: 34, height: 34, borderRadius: 9, background: cta ? "rgba(21,128,61,0.25)" : C.accentDim, color: cta ? "#86EFAC" : C.accent, display: "flex", alignItems: "center", justifyContent: "center", marginBottom: 11 }}>{icon}</div>
      <div style={{ fontSize: 14.5, fontWeight: 600, color: cta ? "#fff" : C.ink900, marginBottom: 3 }}>{title}</div>
      <div style={{ fontSize: 12.5, color: cta ? C.slate400 : C.slate500, lineHeight: 1.5 }}>{desc}</div>
      {cta && <div style={{ marginTop: 10, fontSize: 12.5, fontWeight: 600, color: "#86EFAC" }}>Scopri come →</div>}
    </div>
  );
}

function NavLink({ children }) {
  return <span style={{ fontSize: 13.5, fontWeight: 500, color: "#CBD5E1", cursor: "pointer" }}>{children}</span>;
}
function SearchIcon() { return <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><circle cx="11" cy="11" r="7"/><path d="m21 21-4-4"/></svg>; }
function TrophyIcon() { return <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M6 9H4a2 2 0 0 1-2-2V5h4M18 9h2a2 2 0 0 0 2-2V5h-4M6 5h12v4a6 6 0 0 1-12 0V5ZM9 18h6M10 22h4M12 15v3"/></svg>; }
function HorseIcon() { return <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M5 21V11l3-3 4 1 3-4 4 2v3M5 11l-2 2M15 21v-5l-3-2"/></svg>; }
function FlagIcon() { return <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M4 22V4M4 4h11l-2 4 2 4H4"/></svg>; }
